={{ ((parameter) => { function getInputs(parameters) {
    const inputs = [
        { displayName: '', type: 'main' },
        {
            displayName: 'Model',
            maxConnections: 1,
            type: 'ai_languageModel',
            required: true,
        },
    ];
    const needsFallback = parameters?.needsFallback;
    if (needsFallback === true) {
        inputs.push({
            displayName: 'Fallback Model',
            maxConnections: 1,
            type: 'ai_languageModel',
            required: true,
        });
    }
    const hasOutputParser = parameters?.hasOutputParser;
    if (hasOutputParser === undefined || hasOutputParser === true) {
        inputs.push({
            displayName: 'Output Parser',
            type: 'ai_outputParser',
            maxConnections: 1,
            required: false,
        });
    }
    return inputs;
}; return getInputs(parameter) })($parameter) }}

={{ ((parameter) => { function getInputs(parameters) {
    const chunkingMode = parameters?.chunkingMode;
    const operationMode = parameters?.operationMode;
    const inputs = [
        { displayName: '', type: 'main' },
        {
            displayName: 'Model',
            maxConnections: 1,
            type: 'ai_languageModel',
            required: true,
        },
    ];
    if (operationMode === 'documentLoader') {
        inputs.push({
            displayName: 'Document',
            type: 'ai_document',
            required: true,
            maxConnections: 1,
        });
        return inputs;
    }
    if (chunkingMode === 'advanced') {
        inputs.push({
            displayName: 'Text Splitter',
            type: 'ai_textSplitter',
            required: false,
            maxConnections: 1,
        });
        return inputs;
    }
    return inputs;
}; return getInputs(parameter) })($parameter) }}

